class Solution:
    def crackSafe(self, n: int, k: int) -> str:
        total = k ** n
        seen = {'0' * n}
        path = ['0'] * n

        def dfs(node):
            if len(seen) == total:
                return True
            for d in range(k):
                nxt = node[1:] + str(d)
                if nxt not in seen:
                    seen.add(nxt)
                    path.append(str(d))
                    if dfs(nxt):
                        return True
                    seen.remove(nxt)
                    path.pop()
            return False

        dfs('0' * n)
        return ''.join(path)

