class Solution {
    private int total, k;
    private Set<String> seen = new HashSet<>();
    private StringBuilder path = new StringBuilder();

    private boolean dfs(String node) {
        if (seen.size() == total) return true;
        for (int d = 0; d < k; d++) {
            String nxt = node.substring(1) + d;
            if (!seen.contains(nxt)) {
                seen.add(nxt);
                path.append(d);
                if (dfs(nxt)) return true;
                seen.remove(nxt);
                path.deleteCharAt(path.length() - 1);
            }
        }
        return false;
    }

    public String crackSafe(int n, int k) {
        this.k = k;
        total = 1;
        for (int i = 0; i < n; i++) total *= k;
        char[] start = new char[n];
        Arrays.fill(start, '0');
        String s = new String(start);
        seen.add(s);
        path.append(s);
        dfs(s);
        return path.toString();
    }
}

