var crackSafe = function(n, k) {
    const total = Math.pow(k, n);
    const seen = new Set(['0'.repeat(n)]);
    let path = '0'.repeat(n);

    function dfs(node) {
        if (seen.size === total) return true;
        for (let d = 0; d < k; d++) {
            const nxt = node.slice(1) + d;
            if (!seen.has(nxt)) {
                seen.add(nxt);
                path += d;
                if (dfs(nxt)) return true;
                seen.delete(nxt);
                path = path.slice(0, -1);
            }
        }
        return false;
    }

    dfs('0'.repeat(n));
    return path;
};

