class Solution {
    private int k;
    private Set<String> seen = new HashSet<>();
    private StringBuilder res = new StringBuilder();

    private void dfs(String v) {
        for (int d = 0; d < k; d++) {
            String e = v + d;
            if (!seen.contains(e)) {
                seen.add(e);
                dfs(e.substring(1));
                res.append(d);
            }
        }
    }

    public String crackSafe(int n, int k) {
        this.k = k;
        if (n == 1) {
            StringBuilder sb = new StringBuilder();
            for (int d = 0; d < k; d++) sb.append(d);
            return sb.toString();
        }
        char[] c = new char[n - 1];
        Arrays.fill(c, '0');
        dfs(new String(c));
        return res.toString() + new String(c);
    }
}

